import { localDate, weekDays, summary, snapshot, previousSets, records, workoutComparison, warmupSets, validSet, validateBackup } from './domain.js';
import { plan as originalPlan } from './plan.js';
const uuid=()=>crypto.randomUUID(), now=()=>new Date().toISOString(), clone=x=>structuredClone(x);
const days=['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'];
export function createFeatures(c) {
 const {esc:e,icon,number:n,dateLabel:date,openDialog:open,closeDialog:close,render,persist,toast}=c;
 const state=c.getState, catalog=c.getExercises;
 let draft=null, selectedDay=0, month=new Date(), warmupWeights=new Map(), editingSession=null;
 const activePlan=()=>state().plans.find(p=>p.id===state().activePlanId);
 const touch=()=>{state().prefsUpdatedAt=now();};
 const button=(action,label,attrs='',style='secondary-button')=>`<button class="${style}" data-action="${action}" ${attrs}>${label}</button>`;
 const field=(label,id,value,type='text',attrs='')=>`<label class="form-field">${label}<input id="${id}" type="${type}" value="${e(value)}" ${attrs}></label>`;
 function findWorkout(id){return c.getPlan().find(w=>w.id===id)||state().schedule.find(s=>s.workout?.id===id)?.workout;}
 function workoutForDate(d){const slot=state().schedule.find(s=>s.date===localDate(d));return slot?slot.workout:c.getPlan().find(w=>w.day===(d.getDay()+6)%7);}
 const options=(values,value)=>values.map(([v,l])=>`<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(l)}</option>`).join('');
 function planView(){return `<div class="feature-toolbar"><div><div class="eyebrow">EIGENE TRAININGSPLÄNE · AKTIV</div><h2>${e(activePlan().name)}</h2></div>${button('new-plan','+ Eigener Plan')}</div><section class="recommendations"><h2>Empfohlene Trainingspläne</h2><p>Vorlagen nach Trainingstagen, Erfahrung und Ziel auswählen.</p>${button('templates','Empfehlungen ansehen')}</section><div class="feature-toolbar"><h2>Meine Trainingspläne</h2></div><div class="plan-library">${state().plans.map(p=>`<div class="library-row"><div><strong>${e(p.name)}</strong><small>${p.workouts.length} Trainingstage ${p.id===state().activePlanId?'· Aktiv':''}</small></div>${button('edit-plan','Bearbeiten',`data-id="${p.id}"`)}${p.id!==state().activePlanId?button('activate-plan','Aktivieren',`data-id="${p.id}"`):''}${button('copy-plan','Kopieren',`data-id="${p.id}"`,'text-button')}</div>`).join('')}</div><div class="routine-grid plan-grid">${c.getPlan().map((w,i)=>c.routineCard(w,i)).join('')}</div><div class="plan-note">${icon('info')}<p>Ändere deinen Plan für künftige Einheiten. Laufende und abgeschlossene Trainings behalten ihren eigenen Planstand.</p></div>`;}
 function collectDraft(){if(!draft)return;const name=document.querySelector('#plan-name');if(name)draft.name=name.value;const w=draft.workouts[selectedDay];if(!w)return;const nameW=document.querySelector('#workout-name');if(nameW)w.name=nameW.value;const day=document.querySelector('#workout-day');if(day)w.day=Number(day.value);document.querySelectorAll('[data-draft-ex]').forEach(el=>{const ex=w.exercises[Number(el.dataset.draftEx)];if(ex)ex[el.dataset.prop]=['setCount','restSeconds'].includes(el.dataset.prop)?Number(el.value):el.value;});}
 function editor(){const w=draft.workouts[selectedDay];open(`<div class="eyebrow">PLANEDITOR</div><h2>${draft.id?'Plan bearbeiten':'Dein eigener Plan'}</h2>${field('Planname','plan-name',draft.name,'text','maxlength="100"')}<div class="editor-tabs">${draft.workouts.map((w,i)=>button('draft-day',`${days[w.day].slice(0,2)} · ${e(w.name)}`,`data-index="${i}"`,i===selectedDay?'primary-button':'secondary-button')).join('')}</div>${w?`${field('Name der Einheit','workout-name',w.name,'text','maxlength="100"')}<label class="form-field">Wochentag<select id="workout-day">${options(days.map((d,i)=>[i,d]),w.day)}</select></label><div class="editor-exercises">${w.exercises.map((ex,i)=>`<article class="editor-exercise"><header><strong>${i+1}. ${e(ex.name)}</strong><div>${button('move-ex','↑',`data-index="${i}" data-direction="-1" aria-label="${e(ex.name)} nach oben"`,'icon-button small')}${button('move-ex','↓',`data-index="${i}" data-direction="1" aria-label="${e(ex.name)} nach unten"`,'icon-button small')}${button('drop-ex',icon('trash'),`data-index="${i}" aria-label="${e(ex.name)} entfernen"`,'icon-button small')}</div></header><div class="editor-fields">${[['setCount','Sätze',ex.setCount??2,'number','min="1" max="30" step="1"'],['target','Ziel-Wdh.',ex.target,'text','maxlength="100"'],['rir','RIR',ex.rir??'Satz 1: 0–1 · Satz 2: 2–3','text','maxlength="100"'],['restSeconds','Pause (Sek.)',ex.restSeconds??state().preferences.restSeconds,'number','min="1" max="1800" step="1"']].map(([prop,label,value,type,attr])=>`<label>${label}<input data-draft-ex="${i}" data-prop="${prop}" type="${type}" value="${e(value)}" ${attr}></label>`).join('')}</div></article>`).join('')}</div><label class="form-field">Übungsdatenbank durchsuchen<input id="exercise-search" placeholder="Name oder Muskelgruppe …"></label><select id="add-exercise" aria-label="Übung auswählen">${catalog().filter(ex=>!w.exercises.some(v=>v.id===ex.id)).map(ex=>`<option value="${ex.id}">${e(ex.name)} · ${e(ex.muscle)}</option>`).join('')}</select><div class="feature-toolbar">${button('draft-add-ex','Übung hinzufügen')}${button('custom-exercise','Eigene Übung anlegen')}${button('drop-day','Einheit entfernen','','text-button danger')}</div>`:'<p>Lege zuerst einen Trainingstag an.</p>'}${draft.workouts.length<7?button('add-day','+ Trainingstag'):''}<div class="dialog-footer">${button('save-plan','Plan speichern','','primary-button full-width')}</div>`,'Planeditor');}
 const templates=[
  {name:'V11 · Fünf Tage',days:5,level:'Erfahren',equipment:'Gym',goal:'Muskelaufbau',why:'Push, Pull, Legs + Core, Upper, Lower. Deine vollständige Ausgangsvorlage für fünf feste Trainingstage.',workouts:()=>clone(originalPlan)},
  {name:'Upper / Lower · Vier Tage',days:4,level:'Erfahren',equipment:'Gym',goal:'Muskelaufbau',why:'Zwei Oberkörper- und zwei Unterkörpereinheiten. Für vier verfügbare Tage und wiederkehrende Übungspraxis.',workouts:()=>[3,4,3,4].map((i,j)=>({...clone(originalPlan[i]),day:[0,1,3,4][j]}))},
  {name:'Ganzkörper · Drei Tage',days:3,level:'Einstieg',equipment:'Gym',goal:'Grundlagen',why:'Drei übersichtliche Einheiten mit freien Tagen dazwischen. Weniger Übungen pro Einheit als im V11-Split.',workouts:()=>[0,2,4].map((day,j)=>({id:uuid(),name:`Ganzkörper ${'ABC'[j]}`,day,letter:'ABC'[j],exercises:[originalPlan[2].exercises[0],originalPlan[0].exercises[0],originalPlan[1].exercises[1],originalPlan[2].exercises[2],originalPlan[2].exercises[6]].map(ex=>({...clone(ex),setCount:2,rir:'2–3'}))}))}
 ];
 function templateView(){open(`<div class="eyebrow">TRAININGSVORLAGEN</div><h2>Ein Ausgangspunkt für dich.</h2><p>Wähle nach verfügbaren Tagen, Erfahrung, Ziel und Ausrüstung. Jede Vorlage wird als eigene, frei bearbeitbare Kopie angelegt.</p><div class="template-filters">${[['template-days','Tage',[['','Alle'],[3,'3'],[4,'4'],[5,'5']]],['template-level','Erfahrung',[['','Alle'],['Einstieg','Einstieg'],['Erfahren','Erfahren']]],['template-goal','Ziel',[['','Alle'],['Grundlagen','Grundlagen'],['Muskelaufbau','Muskelaufbau']]],['template-equipment','Ausrüstung',[['','Alle'],['Gym','Gym']]]].map(([id,label,opts])=>`<label class="form-field">${label}<select id="${id}" data-template-filter>${options(opts,'')}</select></label>`).join('')}</div><div id="template-results">${templateCards()}</div>`,'Trainingsvorlagen');}
 function templateCards(){const val=id=>document.querySelector('#'+id)?.value||'';const matches=templates.map((t,i)=>({...t,index:i})).filter(t=>(!val('template-days')||t.days===Number(val('template-days')))&&(!val('template-level')||t.level===val('template-level'))&&(!val('template-goal')||t.goal===val('template-goal'))&&(!val('template-equipment')||t.equipment===val('template-equipment')));return matches.length?matches.map(t=>`<article class="template-card"><h3>${t.name}</h3><div class="detail-tags"><span>${t.days} Tage</span><span>${t.level}</span><span>${t.goal}</span><span>${t.equipment}</span></div><p>${t.why}</p>${button('use-template','Als eigenen Plan übernehmen',`data-index="${t.index}"`)}</article>`).join(''):'<p>Keine Vorlage passt zu dieser Auswahl. Du kannst einen eigenen Plan erstellen.</p>';}
 function comparison(s){const v=workoutComparison(s,state().sessions);const earlier=state().sessions.filter(old=>old.id!==s.id&&Date.parse(old.finishedAt)<Date.parse(s.finishedAt));const best=snapshot(s).exercises.flatMap(ex=>{const before=records(earlier,ex),after=records([s],ex);if(!before||!after)return [];const labels=[];if(after.weight>before.weight)labels.push('Gewicht');if(after.reps>before.reps)labels.push('Wiederholungen');if(after.volume>before.volume)labels.push('Volumen');return labels.length?[ex.name+': '+labels.join(', ')]:[];});const badges=best.length?`<section class="comparison-card"><h3>Neue persönliche Bestwerte</h3>${best.map(label=>`<p>${e(label)}</p>`).join('')}</section>`:'';if(!v)return badges+ '<div class="comparison-card"><p>Erste erfasste Einheit dieses Trainings. Beim nächsten Mal kannst du sie vergleichen.</p></div>';return badges+`<section class="comparison-card"><h3>Gegenüber ${date(v.previous.date)}</h3><div class="comparison-values">${[[v.sets,'Sätze'],[v.reps,'Wdh.'],[v.volume,'kg Volumen']].map(([value,label])=>`<div><strong>${value>0?'+':''}${n(value)}</strong><span>${label}</span></div>`).join('')}</div><small>Vergleich der abgeschlossenen Sätze. Mehr Volumen allein bedeutet nicht automatisch mehr Kraft.</small></section>`;}
 function recordView(){const all=catalog().map(ex=>({ex,r:records(state().sessions,ex)})).filter(v=>v.r);return `<details class="records-panel"><summary>Persönliche Rekorde <span>${all.length} Übungen</span></summary>${all.length?`<p>Bestwerte aus deinem gesamten Verlauf. Bei Körpergewichtsübungen zählt kg ausschließlich als Zusatzgewicht.</p><div class="record-list">${all.map(({ex,r})=>`<div><strong>${e(ex.name)}</strong><span>${n(r.weight)} kg ${ex.bodyweight?'Zusatz':''}</span><span>${r.reps} Wdh. / Satz</span><span>${n(r.volume)} kg / Einheit</span></div>`).join('')}</div>`:'<p>Nach dem ersten Training erscheinen hier deine tatsächlichen Bestwerte.</p>'}</details>`;}
 function warmup(ex,source,idx,workout){if(source.bodyweight||workout.exercises.slice(0,idx).some(e=>e.muscle===source.muscle))return '';const kg=ex.sets.find(s=>s.kg!==''&&Number(s.kg)>0)?.kg??ex.warmupKg??previousSets(state().sessions,ex.id)[0]?.kg??'';const sets=warmupSets(kg);return `<details class="warmup" ${!ex.sets.some(v=>v.done||v.reps!=='') && ![0,1].every(i=>state().active.warmups?.includes(`${ex.id}-${i}`))?'open':''}><summary>Warm-up</summary><p>50 % × 5–6 Wdh. und 90 % × 2–3 Wdh., auf 2,5 kg gerundet. Zählt nicht zu deinen Arbeitssätzen.</p><label>Arbeitssatzgewicht (kg)<input type="number" inputmode="decimal" min="0" max="2000" value="${e(kg)}" data-warmup-kg="${ex.id}"></label>${sets.map((s,i)=>`<label class="warmup-check"><input type="checkbox" data-warmup-check="${ex.id}-${i}" ${state().active.warmups?.includes(`${ex.id}-${i}`)?'checked':''}>${n(s.kg)} kg × ${s.reps} Wdh.</label>`).join('')}</details>`;}
 function editSession(id){editingSession=clone(state().sessions.find(s=>s.id===id));const s=editingSession;if(!s)return;open(`<div class="eyebrow">VERLAUF KORRIGIEREN</div><h2>${e(snapshot(s).name)}</h2><div class="editor-fields">${field('Datum','edit-date',s.date,'date',`max="${localDate()}"`)}${field('Dauer (Minuten)','edit-duration',summary(s).minutes,'number','min="1" max="1440"')}</div>${s.exercises.map(ex=>`<section class="session-edit"><h3>${e(snapshot(s).exercises.find(e=>e.id===ex.id).name)}</h3>${ex.sets.map((v,i)=>`<div class="edit-set"><span>${i+1}</span><label>Wdh.<input type="number" min="1" max="1000" step="1" value="${e(v.reps)}" data-edit-ex="${ex.id}" data-edit-set="${i}" data-edit-field="reps"></label><label>kg<input type="number" min="0" max="2000" step="any" value="${e(v.kg)}" data-edit-ex="${ex.id}" data-edit-set="${i}" data-edit-field="kg"></label><label>Erledigt<input type="checkbox" ${v.done?'checked':''} data-edit-ex="${ex.id}" data-edit-set="${i}" data-edit-field="done"></label></div>`).join('')}<label class="form-field">Notiz<input maxlength="3000" data-edit-note="${ex.id}" value="${e(ex.note)}"></label></section>`).join('')}${button('save-edit-session','Korrektur speichern','','primary-button full-width')}`,'Training bearbeiten');}
 function historyTools(){return `<div class="feature-toolbar">${button('calendar','Trainingskalender')}${button('activities','Laufen & Mobility')}</div>`;}
 function calendar(){const start=new Date(month.getFullYear(),month.getMonth(),1,12);const first=weekDays(start)[0], dates=Array.from({length:42},(_,i)=>{const d=new Date(first);d.setDate(d.getDate()+i);return d;});open(`<div class="eyebrow">PLANEN & ZURÜCKBLICKEN</div><div class="feature-toolbar">${button('calendar-month','←','data-offset="-1"','icon-button')}<h2>${date(start,{day:undefined,month:'long',year:'numeric'})}</h2>${button('calendar-month','→','data-offset="1"','icon-button')}</div><div class="month-grid">${days.map(d=>`<small>${d.slice(0,2)}</small>`).join('')}${dates.map(d=>{const key=localDate(d),w=workoutForDate(d),done=state().sessions.some(s=>s.date===key)||state().activities.some(a=>a.date===key);return `<button data-action="calendar-day" data-date="${key}" class="${d.getMonth()===month.getMonth()?'':'outside'} ${key===localDate()?'today':''}"><strong>${d.getDate()}</strong><span>${done?'✓':w?e(w.name):'—'}</span></button>`;}).join('')}</div><p class="muted">Tippe auf einen Tag, um ihn zu planen, zu verschieben oder absolvierte Einheiten zu öffnen.</p>`,'Trainingskalender');}
 function scheduleDay(key){c.setSelected(new Date(key+'T12:00:00'));const w=workoutForDate(c.getSelected());open(`<div class="eyebrow">${date(key,{weekday:'long',year:'numeric'})}</div><h2>${w?e(w.name):'Ruhetag'}</h2>${state().sessions.filter(s=>s.date===key).map(s=>button('session',`Absolviert: ${e(snapshot(s).name)}`,`data-id="${s.id}"`,'secondary-button full-width')).join('')}<label class="form-field">Einheit an diesem Tag<select id="schedule-workout">${options([['','Ruhetag'],...c.getPlan().map(w=>[w.id,w.name])],w?.id||'')}</select></label>${button('schedule-save','Für diesen Tag speichern',`data-date="${key}"`,'primary-button full-width')}${w?`${field('Einheit verschieben auf','move-date',key,'date')}<p class="muted">Am bisherigen Tag entsteht ein Ruhetag. Eine Planung am Zieltag wird ersetzt; abgeschlossene Trainings bleiben erhalten.</p>${button('schedule-move','Einheit verschieben',`data-date="${key}"`,'secondary-button full-width')}`:''}${button('schedule-reset','Wieder dem Wochenplan folgen',`data-date="${key}"`,'text-button full-width')}`,'Trainingstag planen');}
 function setSlot(key,w){const id=`slot-${key}`;state().schedule=state().schedule.filter(v=>v.id!==id);state().schedule.push({id,date:key,workout:w?clone(w):null,updatedAt:now()});delete state().deleted[id];}
 function activityLinks(){return `<div class="activity-links"><div><h3>Auch abseits der Hantel.</h3><p>Laufen und Mobility separat erfassen.</p></div>${button('log-run','+ Lauf')}${button('log-mobility','+ Mobility')}${button('calendar','Kalender')}</div>`;}
 function activities(){const a=[...state().activities].sort((a,b)=>b.date.localeCompare(a.date));open(`<div class="eyebrow">LAUFEN & MOBILITY</div><h2>Bewegung in jeder Form.</h2><div class="feature-toolbar">${button('log-run','+ Lauf')}${button('log-mobility','+ Mobility')}</div>${a.length?a.map(a=>`<article class="activity-row"><strong>${e(a.name)}</strong><p>${date(a.date)} · ${n(a.minutes)} min${a.type==='run'?` · ${n(a.km)} km · ${e(a.zone)}${a.km>0?` · ${n(a.minutes/a.km)} min/km`:''}`:''}</p><small>${e(a.note)}</small>${button('delete-activity','Löschen',`data-id="${a.id}"`,'text-button danger')}</article>`).join(''):'<p>Noch keine Einträge. Du bestimmst Inhalt, Dauer und Intensität.</p>'}`,'Aktivitäten');}
 function logActivity(type){open(`<div class="eyebrow">${type==='run'?'LAUFEN':'MOBILITY'}</div><h2>Einheit erfassen</h2>${field(type==='run'?'Bezeichnung':'Übung / Einheit','activity-name',type==='run'?'Lauf':'','text','maxlength="100"')}${field('Datum','activity-date',localDate(),'date',`max="${localDate()}"`)}${field('Dauer (Minuten)','activity-minutes','','number','min="0.1" max="1440" step="any"')}${type==='run'?`${field('Distanz (km)','activity-km','','number','min="0" max="500" step="any"')}<label class="form-field">Art<select id="activity-zone">${options([['Frei','Frei'],['Zone 2','Zone 2'],['HIIT','HIIT']],'Frei')}</select></label>`:''}<label class="form-field">Notizen<textarea id="activity-note" maxlength="3000" placeholder="Deine Übungen, Intervalle oder Eindrücke …"></textarea></label>${button('save-activity','Einheit speichern',`data-type="${type}"`,'primary-button full-width')}`,'Aktivität erfassen');}
 function syncView(){return `<section class="sync-card"><div><div class="eyebrow">DEIN KONTO</div><h2>Automatisch gespeichert</h2><p>${e(c.getAccount()?.email||'Mit ChatGPT angemeldet')}</p><p id="sync-status">${e(c.getSync().status())}</p><small>Abgeschlossene Trainings, Pläne und Aktivitäten werden automatisch in deinem Konto gespeichert. Laufende Trainings bleiben auf diesem Gerät. Offline-Änderungen werden beim Wiederverbinden übertragen.</small></div><div>${button('sync-now','Jetzt abgleichen','','primary-button')}${button('logout','Abmelden')}</div></section>${c.hasLegacyState()?`<section class="legacy-notice"><h3>Daten aus der bisherigen Version</h3><p>Frühere lokale Daten wurden noch keinem Konto zugeordnet.</p>${button('legacy-import','Eigene lokale Daten übernehmen')}</section>`:''}`;}
 async function handle(action,b){const id=b.dataset.id, i=Number(b.dataset.index);switch(action){
 case 'new-plan':draft={id:null,name:'Mein neuer Plan',workouts:[]};selectedDay=0;editor();break;
 case 'edit-plan':draft=clone(state().plans.find(p=>p.id===id));selectedDay=0;editor();break;
 case 'copy-plan':{const p=clone(state().plans.find(p=>p.id===id));p.id=uuid();p.name+=' · Kopie';p.updatedAt=now();p.workouts.forEach(w=>w.id=uuid());state().plans.push(p);persist();render();break;}
 case 'activate-plan':state().activePlanId=id;touch();persist();render();toast('Plan aktiviert. Laufendes Training bleibt unverändert.');break;
 case 'draft-day':collectDraft();selectedDay=i;editor();break;
 case 'add-day':collectDraft();draft.workouts.push({id:uuid(),name:'Neue Einheit',day:days.findIndex((_,i)=>!draft.workouts.some(w=>w.day===i)),letter:'',exercises:[]});selectedDay=draft.workouts.length-1;editor();break;
 case 'drop-day':collectDraft();draft.workouts.splice(selectedDay,1);selectedDay=Math.max(0,selectedDay-1);editor();break;
 case 'move-ex':{collectDraft();const arr=draft.workouts[selectedDay].exercises,j=i+Number(b.dataset.direction);if(j>=0&&j<arr.length)[arr[i],arr[j]]=[arr[j],arr[i]];editor();break;}
 case 'drop-ex':collectDraft();draft.workouts[selectedDay].exercises.splice(i,1);editor();break;
 case 'draft-add-ex':{const ex=catalog().find(e=>e.id===document.querySelector('#add-exercise').value);if(!ex){toast('Bitte zuerst eine Übung auswählen.');break;}collectDraft();draft.workouts[selectedDay].exercises.push({...clone(ex),setCount:2});editor();break;}
 case 'custom-exercise':collectDraft();open(`<h2>Eigene Übung</h2>${field('Name','custom-name','','text','maxlength="100"')}${field('Muskelgruppe','custom-muscle','','text','maxlength="100"')}<label class="form-field">Gewichtserfassung<select id="custom-bw">${options([['no','Gesamtgewicht'],['yes','Körpergewicht + Zusatzgewicht']],'no')}</select></label>${button('save-custom','Übung übernehmen','','primary-button full-width')}`);break;
 case 'save-custom':{const name=document.querySelector('#custom-name').value.trim(),muscle=document.querySelector('#custom-muscle').value.trim();if(!name||!muscle){toast('Bitte Name und Muskelgruppe eintragen.');break;}draft.workouts[selectedDay].exercises.push({id:uuid(),name,muscle,bodyweight:document.querySelector('#custom-bw').value==='yes',target:'8–12',note:'',setCount:2,rir:'2–3'});editor();break;}
 case 'save-plan':{collectDraft();if(!draft.name.trim()||!draft.workouts.length||draft.workouts.some(w=>!w.name.trim()||!w.exercises.length)||new Set(draft.workouts.map(w=>w.day)).size!==draft.workouts.length){toast('Bitte Namen, mindestens eine Übung je Einheit und unterschiedliche Wochentage festlegen.');break;}if(draft.workouts.some(w=>w.exercises.length>40||w.exercises.some(ex=>!Number.isInteger(ex.setCount??2)||(ex.setCount??2)<1||(ex.setCount??2)>30||!ex.target.trim()||!Number.isInteger(ex.restSeconds??120)||(ex.restSeconds??120)<1||(ex.restSeconds??120)>1800))){toast('Sätze: 1–30. Pause: 1–1800 Sekunden. Bitte Ziele ausfüllen.');break;}draft.id||=uuid();draft.updatedAt=now();state().plans=state().plans.filter(p=>p.id!==draft.id);state().plans.push(clone(draft));persist();close();render();toast('Plan gespeichert. Bei Bedarf in der Planliste aktivieren.');break;}
 case 'templates':templateView();break;
 case 'use-template':{const t=templates[i],p={id:uuid(),name:t.name,updatedAt:now(),workouts:t.workouts()};p.workouts.forEach(w=>w.id=uuid());state().plans.push(p);persist();close();render();toast('Vorlage als eigener Plan gespeichert. Noch nicht aktiviert.');break;}
 case 'warmup-calc':{const input=document.querySelector(`[data-warmup-kg="${b.dataset.ex}"]`);if(Number(input.value)<=0||Number(input.value)>2000){toast('Bitte ein positives Arbeitssatzgewicht bis 2000 kg eingeben.');break;}warmupWeights.set(b.dataset.ex,Number(input.value));const opened=[...document.querySelectorAll('.warmup[open]')].map(el=>el.querySelector('[data-warmup-kg]').dataset.warmupKg);render();document.querySelectorAll('.warmup').forEach(el=>{if(opened.includes(el.querySelector('[data-warmup-kg]').dataset.warmupKg))el.open=true;});break;}
 case 'edit-session':editSession(id);break;
 case 'save-edit-session':{const s=editingSession, d=document.querySelector('#edit-date').value,m=Number(document.querySelector('#edit-duration').value);if(!d||d>localDate()||!Number.isFinite(m)||m<1||m>1440||!s.exercises.some(ex=>ex.sets.some(v=>v.done))||s.exercises.some(ex=>ex.sets.some(v=>v.done&&!validSet(v)))){toast('Bitte Datum, Dauer und abgeschlossene Sätze prüfen.');break;}if(d!==s.date)s.startedAt=new Date(d+'T12:00:00').toISOString();s.date=d;s.finishedAt=new Date(Date.parse(s.startedAt)+m*60000).toISOString();s.updatedAt=now();try{validateBackup({...state(),sessions:state().sessions.map(v=>v.id===s.id?s:v)});}catch{toast('Bitte auch nicht abgeschlossene Satzwerte prüfen.');break;}state().sessions=state().sessions.map(v=>v.id===s.id?s:v);persist();close();render();toast('Training korrigiert. Statistiken und Rekorde aktualisiert.');break;}
 case 'calendar':calendar();break;
 case 'calendar-month':month.setDate(1);month.setMonth(month.getMonth()+Number(b.dataset.offset));calendar();break;
 case 'calendar-day':scheduleDay(b.dataset.date);break;
 case 'schedule-save':{const w=findWorkout(document.querySelector('#schedule-workout').value);setSlot(b.dataset.date,w);persist();close();render();toast('Trainingstag gespeichert.');break;}
 case 'schedule-move':{const target=document.querySelector('#move-date').value,source=b.dataset.date;if(!target||target===source){toast('Bitte einen anderen Tag wählen.');break;}const w=workoutForDate(new Date(source+'T12:00:00'));setSlot(source,null);setSlot(target,w);persist();close();render();toast('Einheit verschoben.');break;}
 case 'schedule-reset':{const id=`slot-${b.dataset.date}`;state().schedule=state().schedule.filter(s=>s.id!==id);state().deleted[id]=now();persist();close();render();break;}
 case 'activities':activities();break;
 case 'log-run':logActivity('run');break;
 case 'log-mobility':logActivity('mobility');break;
 case 'save-activity':{const name=document.querySelector('#activity-name').value.trim(),d=document.querySelector('#activity-date').value,minutes=Number(document.querySelector('#activity-minutes').value),km=Number(document.querySelector('#activity-km')?.value||0);if(!name||!d||d>localDate()||!Number.isFinite(minutes)||minutes<=0||minutes>1440||!Number.isFinite(km)||km<0||km>500){toast('Bitte Name, Datum, Dauer und Distanz prüfen.');break;}state().activities.push({id:uuid(),name,date:d,type:b.dataset.type,minutes,km,zone:document.querySelector('#activity-zone')?.value||'',note:document.querySelector('#activity-note').value,updatedAt:now()});persist();activities();toast('Aktivität gespeichert.');break;}
 case 'delete-activity':open(`<h2>Aktivität löschen?</h2><p>Dieser Eintrag wird aus deinem Verlauf entfernt.</p>${button('confirm-delete-activity','Eintrag löschen',`data-id="${id}"`,'primary-button full-width')}`);break;
 case 'confirm-delete-activity':state().activities=state().activities.filter(a=>a.id!==id);state().deleted[id]=now();persist();activities();break;
 
 case 'sync-now':await c.getSync().run();render();break;
 default:return false;
 }return true;}
 function input(el){if(el.id==='exercise-search'){const q=el.value.toLowerCase();document.querySelector('#add-exercise').innerHTML=catalog().filter(ex=>!draft.workouts[selectedDay].exercises.some(v=>v.id===ex.id)&&(ex.name+' '+ex.muscle).toLowerCase().includes(q)).map(ex=>`<option value="${ex.id}">${e(ex.name)} · ${e(ex.muscle)}</option>`).join('');}if(el.dataset.editEx&&editingSession){const set=editingSession.exercises.find(ex=>ex.id===el.dataset.editEx).sets[Number(el.dataset.editSet)];set[el.dataset.editField]=el.dataset.editField==='done'?el.checked:el.value;}if(el.dataset.editNote&&editingSession)editingSession.exercises.find(ex=>ex.id===el.dataset.editNote).note=el.value;}
 function refreshWarmup(el){const workout=snapshot(state().active),id=el.dataset.ex||el.dataset.warmupKg,ex=state().active.exercises.find(v=>v.id===id),idx=workout.exercises.findIndex(v=>v.id===id),node=el.closest('.exercise-card')?.querySelector('.warmup');if(node&&ex)node.outerHTML=warmup(ex,workout.exercises[idx],idx,workout);}
 function change(el){if(el.hasAttribute('data-template-filter'))document.querySelector('#template-results').innerHTML=templateCards();if(el.dataset.warmupCheck&&state().active){state().active.warmups||=[];state().active.warmups=state().active.warmups.filter(v=>v!==el.dataset.warmupCheck);if(el.checked)state().active.warmups.push(el.dataset.warmupCheck);persist();render();}}
 return {refreshWarmup,planView,findWorkout,workoutForDate,comparison,recordView,warmup,historyTools,activityLinks,syncView,handle,input,change};
}
